        "desc": "使指定敌方单体陷入【负债证明】状态，使其受到的追加攻击伤害提高【25%/50%】。【负债证明】仅对最新被施加的目标生效，我方目标回合开始或行动时，若场上不存在陷入【负债证明】状态的敌方目标，托帕使随机敌方目标陷入【负债证明】状态。\n使账账对该目标造成等同于托帕【75%/150%】攻击力的火属性伤害。施放此战技造成伤害时，被视为发动了追加攻击。",
