        "desc": "托帕入场时召唤账账，账账会自动搜寻一定范围内的普通战利品与扑满。\n主动施放秘技使下一场战斗中账账施放首次攻击后，托帕恢复60点能量。\n主动施放秘技与大地图内的敌人战斗胜利后，若托帕仍在队伍中，则在获取信用点时额外获取少量信用点，每个地球日内最多额外获取10,000点。\n主动施放秘技与模拟宇宙、差分宇宙内的敌人战斗胜利后，额外获取少量宇宙碎片并有小概率获得1个随机奇物。",
