        "name": "无端命运的机杼",
        "desc": "敌方目标每回合开始时每受到1次持续伤害，有【50%/65%】的基础概率陷入1层【奥迹】。\n【奥迹】状态下，敌方目标每回合开始时受到等同于黑天鹅【96%/240%】攻击力的风属性持续伤害，每层【奥迹】使此伤害倍率提高【4.8%/12.0%】，随后重置为1层。【奥迹】最多叠加50层。\n仅在敌方目标回合开始【奥迹】造成伤害时，黑天鹅根据目标陷入的【奥迹】层数触发额外效果：\n大于等于3层：对相邻目标造成等同于黑天鹅【72%/180%】攻击力的风属性持续伤害，并且有【50%/65%】的基础概率使相邻目标陷入1层【奥迹】。\n大于等于7层：使本次造成的持续伤害无视该目标及其相邻目标20%的防御力。",
