        "name": "剑为地纪，刃惊天宗/勘破•斩/勘破•灭",
        "desc": "【剑为地纪，刃惊天宗】消耗120点能量，云璃获得【格挡】并使敌方全体陷入嘲讽状态，持续至下一个我方或敌方回合结束时。并使云璃下一次反击造成的暴击伤害提高【60%/100%】。触发天赋的反击效果时，将替换为发动反击【勘破•灭】同时移除【格挡】效果。若【格挡】状态期间没有触发反击，状态结束时云璃立即对随机敌方目标发动反击【勘破•斩】。\n云璃通过此技能造成伤害时，被视为造成了终结技伤害。\n【勘破•斩】对目标造成等同于云璃【132%/220%】攻击力的物理属性伤害，对其相邻目标造成等同于云璃【66%/110%】攻击力的物理属性伤害。\n【勘破•灭】对目标造成等同于云璃【132%/220%】攻击力的物理属性伤害，对其相邻目标造成等同于云璃【66%/110%】攻击力的物理属性伤害，随后额外造成6次伤害，每次伤害对随机敌方单体造成等同于云璃【43%/72%】攻击力的物理伤害。",
