    "positioning": "椒丘是一名通过对敌方施加【烬煨】使敌方受到的伤害提高且对敌方造成灼烧伤害的辅助型角色。椒丘施放终结技后开启结界，处于结界中的敌方目标受到的终结技伤害提高。",
    "intro": "仙舟「曜青」 · 椒丘是一名通过对敌方施加【烬煨】使敌方受到的伤害提高且对敌方造成灼烧伤害的辅助型角色。椒丘施放终结技后开启结界，处于结界中的敌方目标受到的终结技伤害提高。",
