        "tag": "天赋",
        "name": "四示八权，纤滋精味",
        "desc": "妨害\n椒丘使用普攻、战技、终结技击中敌人时，有100%的基础概率对其施加1层【烬煨】，1层时使敌人受到的伤害提高【7.5%/15.0%】，此后每叠加1层提高【2.5%/5.0%】。\n【烬煨】最多叠加5层，持续2回合。\n当敌方目标处于【烬煨】状态时，也会被视为同时陷入了灼烧状态，每回合开始时受到等同于椒丘【90%/180%】攻击力的火属性持续伤害。",
