        "name": "凿破大荒/闪裂刃舞/钺贯天冲",
        "desc": "【凿破大荒】对指定敌方单体造成最多等同于飞霄【402%/700%】攻击力的风属性伤害，期间可无视弱点属性削减目标韧性，目标未处于弱点击破状态时飞霄的弱点击破效率提高100%。\n其中，飞霄先对该目标发动【闪裂刃舞】或【钺贯天冲】，总计6次。最后对该目标造成等同于飞霄【96%/160%】攻击力的风属性伤害。\n【闪裂刃舞】对所选目标造成等同于飞霄【36%/60%】攻击力的风属性伤害。若目标处于弱点击破状态，伤害倍率提高【15%/30%】。\n【钺贯天冲】对所选目标造成等同于飞霄【36%/60%】攻击力的风属性伤害。若目标未处于弱点击破状态，伤害倍率提高【15%/30%】。",
