        "name": "雷狩",
        "desc": "【飞黄】达到6点时可激活终结技，最多累计12点。我方目标每施放2次攻击后，飞霄获得1点【飞黄】，飞霄的终结技攻击不计入次数。\n当飞霄的队友对敌方目标施放攻击后，飞霄立即对主目标发动追加攻击，造成等同于飞霄【55%/110%】攻击力的风属性伤害。若不存在可攻击的主目标，则攻击敌方随机单体。该效果每回合最多触发1次，飞霄回合开始时重置可触发次数。发动此攻击时使自身造成的伤害提高【30%/60%】，持续2回合。",
