        "key": "technique",
        "tag": "秘技",
        "name": "岚身",
        "desc": "使用秘技后进入持续20秒的【陷锋】状态。【陷锋】状态下会牵引一定范围内的敌人，并且自身移动速度提高50%，进入战斗后获得1点【飞黄】。\n【陷锋】状态下主动攻击会使所有牵引的敌人进入战斗。进入战斗后，每个波次开始时对敌方全体造成等同于飞霄200%攻击力的风属性伤害，该伤害必定造成暴击。若牵引了超过1个敌人，每超过1个敌人，该伤害的倍率提高100%，最多提高至1,000%。",
