        "name": "有道祥见,衔书摇风",
        "desc": "使指定我方单体获得【狐祈】,并使自身进入【炽灼】状态,持续3回合,忘归人每回合开始时持续回合数减1.,且【狐祈】仅对忘归人战技最新的施放目标生效。\n持有【狐祈】:的我方目标;击破特攻提高【15%/30%】,攻击没有对应属性弱点的敌人也能削减韧性，效果等同于原削韧值的50%,无法与其他无视弱点属性削韧效果叠加。\n处于【炽灼】.状态时,忘归人普攻获得强化。持有【狐祈】的我方目标每次施放攻击时，忘归人有100%的基础概率使受到攻击的敌方目标防御力降低【8%/18%】，持续2回合。",
