        "tag": "战技",
        "name": "格局打开/我有一个大胆的想法",
        "desc": "【格局打开】对指定敌方单体造成等同于大黑塔【35%/70%】攻击力的冰属性伤害并施加1层【解读】。对本次战技命中过的目标及其相邻目标造成等同于大黑塔【35%/70%】攻击力的冰属性伤害，该效果可重复2次。\n【我有一个大胆的想法】消耗1层【灵感】，对指定敌方单体造成等同于大黑塔【40%/80%】攻击力的冰属性伤害并施加1层【解读】。对本次战技中被击中过的目标及其相邻目标造成等同于大黑塔【40%/80%】攻击力的冰属性伤害，重复2次，最后，对所有敌方目标造成等同于大黑塔【20%/40%】攻击力的冰属性伤害。",
