        "tag": "天赋",
        "name": "拿来吧你",
        "desc": "敌方目标进入战斗时，大黑塔对其施加1层【解读】。每个波次开始时，对一个随机敌方目标施加25层【解读】，优先施加给精英级别及以上的目标。强化战技的主目标持有【解读】时，造成的伤害倍率提高，每层对主目标/其他目标提高【【4%/8%】/【2%/4%】】，若队伍中的「智识」命途角色大于等于2名，每层额外对主目标/其他目标提高【【4%/8%】/【2%/4%】】。【解读】最多可叠加42层，使用强化战技时，将主目标的【解读】重置为1层。敌方目标离场或被任意单位消灭后，【解读】会被转移，优先转移到精英级别及以上的目标。",
