        "desc": "【万死无悔】消耗等同于万敌当前生命值50%的生命值，对指定敌方单体造成等同于万敌【45%/90%】生命上限的虚数属性伤害，同时对其相邻目标造成等同于万敌【25%/50%】生命上限的虚数属性伤害。\n若当前生命值不足，施放战技时万敌的当前生命值降低至1点。\n【弑王成王】消耗等同于万敌当前生命值35%的生命值，对敌方单体造成等同于万敌【55%/110%】生命上限的虚数属性伤害，同时对其相邻目标造成等同于万敌【33%/66%】生命上限的虚数属性伤害。\n若当前生命值不足，施放战技时万敌的当前生命值降低至1点。\n该技能会自动施放。\n【弑神登神】消耗150点充能，对敌方单体造成等同于万敌【140%/280%】生命上限的虚数属性伤害，同时对其相邻目标造成等同于万敌【84%/168%】生命上限的虚数属性伤害。\n该技能会自动施放。此技能期间无法积攒充能。",
