        "name": "掌心淌过的荒芜/月茧之庇",
        "desc": "【掌心淌过的荒芜】【新蕊】上限与场上全体角色等级有关，我方全体每损失1点生命值遐蝶获得1点【新蕊】，当【新蕊】达到上限时可激活终结技。我方损失生命值时,遐蝶与死龙造成的伤害提高【10%/20%】，该效果最多叠加3层,持续3回合。\n死龙在场时无法通过天赋获得【新蕊】，除死龙以外我方全体每损失1点生命值会转化为死龙同等的生命值。\n【月茧之庇】获取遐蝶后或当前队伍存在遐蝶时获得效果：战斗中，若我方角色受到致命攻击，则本次行动中所有受到致命攻击的我方角色获得【月茧】状态。【月茧】状态下的角色会暂时延后陷入无法战斗状态,且可以正常行动。若行动后，下一次回合开始前当前生命值提高或获得护盾，则解除【月茧】状态，否则将立即陷入无法战斗状态。该效果单场战斗中最多触发1次。",
