        "desc": "使用秘技后进入持续20秒的【冥茫】状态。【冥茫】状态下敌人无法主动靠近遐蝶。\n【冥茫】状态下主动攻击会使所有范围内的敌人进入战斗，同时召唤忆灵死龙使其行动提前100%并展开境界【遗世冥域】，死龙拥有等同于【新蕊】上限50%的当前生命值。进入战斗后，消耗除死龙以外的我方全体40%当前生命值。\n进入战斗后未召唤死龙则遐蝶获得等同于【新蕊】上限30%点数的【新蕊】。",
