        "desc": "敌方目标当前生命值小于等于自身生命上限 80% / 50% 时，【骸爪，冥龙之环拥】、【擘裂冥茫的爪痕】、【燎尽黯泽的焰息】、【灼掠幽墟的晦翼】对其造成的伤害为原伤害的 120% / 140% 。"
