        "name": "永劫燔世，其将背负",
        "desc": "【永劫燔世，其将背负】变身为卡厄斯兰那，变身期间展开境界。境界内的其他队友离场且无法行动，敌方全体始终拥有物理属性弱点。\n卡厄斯兰那不会进入自己的回合，但拥有8个卡厄斯兰那的额外回合，速度固定为卡厄斯兰那基础速度的60%。最后的卡厄斯兰那的额外回合开始时立即发动最后一击，造成等同于卡厄斯兰那【480%/960%】攻击力的物理属性终结技伤害，由敌方全体均分。",
