        "name": "谁在害怕康士坦丝？",
        "desc": "进入战斗时，大丽花恢复35点能量，并使自身和另一位开战的队友共同成为【共舞者】。每当场上不存在另一位【共舞者】时，使自身和击破特攻最高的队友共同成为【共舞者】。【共舞者】攻击处于弱点击破状态的敌方目标后，会将本次攻击的削韧值转化为1次【30%/60%】的超击破伤害。\n敌方目标受到另一位【共舞者】攻击后，大丽花发动追加攻击，造成5次伤害，每次对敌方随机单体造成等同于大丽花【15%/30%】 攻击力的火属性伤害。每次对处于弱点击破状态的敌方目标造成伤害后，会将本次伤害的削韧值转化为1次【100%/200%】 的超击破伤害。\n该效果每回合最多触发1次，若追加攻击施放前目标被消灭则对敌方随机单体发动。",
