        "desc": "使指定敌方单体成为【饲饵】，对其造成等同于不死途【100%/200%】攻击力的雷属性伤害。若该目标为【饲饵】，则额外对其造成等同于不死途【50%/100%】攻击力的雷属性伤害，并恢复1点战技点。场上存在【饲饵】时，敌方全体防御力降低【20%/40%】。\n场上不存在【饲饵】时，不死途立即使当前场上生命值最低的敌方单体目标成为【饲饵】，【饲饵】状态仅对最新被施加的目标生效。",
