        "name": "拳头硬了！/奖励关：「狼尊时刻」",
        "desc": "【拳头硬了！】对指定敌方单体造成等同于「银狼LV.999」【50%/100%】攻击力的虚数属性伤害。\n【奖励关：「狼尊时刻」】造成总计等同于「银狼LV.999」【120%/240%】攻击力的虚数属性伤害，均分为100段伤害弹射至敌方随机单体。每弹射一定段数，暂停弹射并触发1次【头号补给盲盒】，总计可触发3次。若对场上所有敌方造成了致命伤害则结束本次技能，当存在可攻击的敌方目标后获得1个额外回合并基于剩余弹射段数和【头号补给盲盒】次数再次施放。每回合首次触发该效果时，使自身所有增益效果延长1回合。\n上述伤害全部结算后发动最后一击，造成等同于「银狼LV.999」【50%/100%】攻击力的虚数属性伤害，由敌方全体均分。\n强化普攻无法恢复战技点。每拥有60点【隐藏分】，强化普攻期间造成的伤害提高原伤害的15%，最多叠加2层。",
