        "name": "无敌玩家，启动!",
        "desc": "进入【无敌玩家】状态并且行动提前100%。\n【无敌玩家】状态下展开结界。「银狼LV.999」持有【好活当赏】时，结界内我方目标每消耗1个战技点，有概率触发1次「银狼LV.999」的【头号补给盲盒】：造成【45%/90%】的虚数属性欢愉伤害，由敌方全体均分，并随机触发1种效果：\n【超超超大剑】：对生命值最高的敌方目标额外造成等同于本次总伤害值20%的真实伤害；\n【爆爆爆炸蛋】：恢复2个战技点；\n【怪怪怪味豆】：获得3个笑点。\n触发该效果的初始固定概率为100%成功触发后下一次触发的固定概率降低至当前概率的20%。若触发前目标被消灭则对新入场的敌方目标触发。",
