        "tag": "天赋",
        "name": "有我在，把把都是顺风局/999安全卫士",
        "desc": "【有我在，把把都是顺风局】【隐藏分】达到60点后可激活终结技，达到上限后还可溢出240点。获得笑点时，「银狼LV.999」获得等量【隐藏分】。每点【隐藏分】使暴击率提高【0.20%/0.40%】。暴击率达到100%后，其余每点【隐藏分】改为使暴击伤害提高【0.40%/0.80%】。\n【无敌玩家】状态下，「银狼LV999」免疫控制类负面状态，无法施放终结技，拥有强化普攻和强化欢愉技，完整施放3次强化普攻后退出【无敌玩家】状态。退出【无敌玩家】状态时【隐藏分】会被清空。\n持有【好活当赏】时，施放普攻、战技对受到攻击的敌方目标造成【20%/40%】的虚数属性欢愉伤害，强化普攻的技能伤害改为相同倍率的欢愉伤害。\n【999安全卫士】获取「银狼LV.999」后或当前队伍存在「银狼LV.999」时获得效果：战斗中，若敌方目标对我方施加了控制类负面状态，则使我方全体获得【防火墙】，持续1回合。【防火墙】状态下，我方目标免疫敌方目标施加的控制类负面状态。该效果每个波次最多触发1次。",
