        "name": "青春•韶华无限",
        "desc": "绯英获得等同于暴击伤害20%的欢愉度。绯英获得能量时，将同步获得等值的【好活当赏】；绯英获得【好活当赏】时，将同步获得等值的能量，单次通过此方式计算的【好活当赏】不超过100点。\n累计获得240点能量时，消耗240点累计值，【狐狸老师】发动追加攻击对敌方全体造成等同于绯英【50%/100%】攻击力的物理属性伤害，为绯英恢复10点能量，单次获得能量时最多获得240点累计值。当绯英持有【好活当赏】时：施放战技可对受到攻击的敌方目标造成【8.0%/16.0%】的物理属性欢愉伤害。\n施放终结技可对敌方全体造成【12%/24%】的物理属性欢愉伤害，并对终结技随机造成伤害的敌方目标造成【14%/28%】的物理属性欢愉伤害，终结技造成欢愉伤害时至少计入等同于能量上限的【好活当赏】。\n【狐狸老师】的追加攻击可对敌方全体造成【12%/25%】的物理属性欢愉伤害。",
