        "desc": "【骸骨当炉，血肉即薪】使敌方全体陷入【煞火缠身】，【煞火缠身】状态下的敌方目标防御力降低【20%/30%】，受到的伤害提高【30%/50%】，持续2回合。随后消耗等同于千冶·刃生命上限20%的生命值展开结界，结界持续期间，千冶·刃获得【无量忿怒】状态。\n【无量忿怒】状态下暴击率提高20%，暴击伤害提高【30%/60%】，普攻获得强化，同时解放战技并获得全新终结技【千冶铸一，万劫烬灭】，若受到致命攻击时，不会陷入无法战斗状态，但会解除结界退出【无量忿怒】状态并回复等同于自身50%生命上限的生命值。\n获得【无量忿怒】状态时，行动序列上出现对应倒计时，倒计时固定拥有70速度，倒计时回合开始时结界解除且退出【无量忿怒】状态。\n若当前生命值不足，施放本技能时千冶·刃的当前生命值降低至1点。\n【千冶铸一，万劫烬灭】对敌方全体造成等同于千冶·刃【210%/350%】生命上限的火属性伤害。",
