        "desc": "【我们，亦是逐星的巨人】立即操控「拓星者」，「拓星者」拥有可对敌方发动6次的【超频粒子光束】或消耗【源能】发动的【轨道歼灭脉冲】，对指定敌方单体最多造成等同于姬子•启行【381%/762%】攻击力的火属性伤害，对其他目标最多造成等同于姬子•启行【126%/252%】攻击力的火属性伤害。\n当【超频粒子光束】次数耗尽时，会自动发动【轨道歼灭脉冲】，随后发动最后一击，造成3次伤害，每次伤害对敌方随机单体造成等同于姬子•启行【40%/80%】攻击力的火属性伤害。\n施放【超频粒子光束】或【轨道歼灭脉冲】对场上所有敌方造成致命伤害或敌方无法被继续削减生命值时，会立即发动最后一击。\n【超频粒子光束】对敌方全体造成等同于姬子•启行【16%/32%】攻击力的火属性伤害，获得1点【源能】，【源能】最多获得3个。\n【轨道歼灭脉冲】消耗1点【源能】对敌方全体造成等同于姬子•启行【10%/20%】攻击力的火属性伤害。当前【源能】大于1点时，每消耗1点【源能】，额外对敌方随机单体造成1次等同于姬子•启行【15%/30%】攻击力的火属性伤害。",
