        "tag": "天赋",
        "name": "「尽情取悦本王吧」/「本王允许你进攻」",
        "desc": "【「尽情取悦本王吧」】我方队友施放终结技时，吉尔伽美什获得【王来背负】，使自身造成的终结技伤害提高20%，持续3回合。\n初始自身回合开始时自动施放普攻。我方其他目标行动时，吉尔伽美什获得1点【兴致】，每拥有1点【兴致】使自身速度提高10%。\n当【兴致】首次达到10点时，进入【来兴致了！】状态，该状态下仅能施放战技，且持续整场战斗。施放战技后，清空自身【兴致】。\n【「本王允许你进攻」】吉尔伽美什或Saber攻击时累计1点攻击计数，任意单位攻击后若累计攻击计数达到8，吉尔伽美什和Saber发动连携追加攻击，对敌方全体分别造成等同于吉尔伽美什【200%/400%】攻击力的雷属性伤害以及Saber【300%/600%】攻击力的风属性伤害，随后吉尔伽美什获得3点【兴致】，Saber固定恢复120点能量并使自身下一次施放终结技时，造成的伤害为原伤害的【120%/200%】。\n施放连携追加攻击后清空累计攻击计数。",
