        "name": "宝石魔术/自在远坂流",
        "desc": "【宝石魔术】进入战斗时，获得20点【宝石能量】。我方目标消耗或恢复战技点时，使其暴击伤害提高【35%/70%】，持续2回合，且每消耗或恢复1点战技点就使远坂凛获得1点【宝石能量】。若远坂凛持有的【宝石能量】大于等于15点或当前战技点大于等于7点，战技强化为【第二魔法实验】。\n【自在远坂流】Archer施放战技【伪·螺旋剑】攻击后，若战技点小于等于3点或本次【回路连接】状态已主动施放5次【伪·螺旋剑]，且未触发【自在远坂流】的连携追加攻击，远坂凛和Archer对敌方全体发动连携追加攻击，分别造成等同于远坂凛【150%/300%】攻击力以及Archer【150%/300%】攻击力的量子属性伤害，并为我方恢复4个战技点。该连携追加攻击仅可触发1次，远坂凛回合结束时重置可触发次数。",
