        "name": "巡游在无界的天空",
        "desc": "忆灵「晴空乐手」初始拥有等同于知更鸟·晴歌70%生命上限的生命上限和等同于知更鸟·晴歌180%速度的速度。我方目标施放攻击时，或在任意目标回合第一次提供治疗效果或护盾时，知更鸟·晴歌获得1点气氛值，上限50点。「晴空乐手」贝茜在场时，若知更鸟·晴歌的气氛值大于等于6点，立即召唤「晴空乐手」啾米，若气氛值大于等于12点，立即召唤「晴空乐手」派丁。当「晴空乐手」全员登台后，解除知更鸟·晴歌与「晴空乐手」陷入的所有控制类负面状态、进入【Fever】状态并展开结界，结界内我方目标造成伤害时无视敌方目标(【10.0%/15.0%】+气氛值*0.5%)防御力。\n处于【Fever】状态时，知更鸟·晴歌与「晴空乐手」免疫控制类负面状态，【Fever】状态结束前知更鸟·晴歌不会进入自己的回合。",
